<?php use App\Models\Ticket; ?>
<section class="ticket-heading"><a class="text-button" href="/list?project=<?= (int)$project['id'] ?>">← Revenir à la liste</a><div><span class="type-icon type-<?= e($ticket['type']) ?>"><?= $ticket['type']==='epic'?'ϟ':'✓' ?></span><span class="ticket-key"><?= e($ticket['key']) ?></span><span class="pill status-<?= e($ticket['status']) ?>"><?= e(Ticket::STATUSES[$ticket['status']]) ?></span><div class="toolbar-spacer"></div><button class="button subtle" data-copy="<?= e(url('/tickets/'.$ticket['id'])) ?>"><?= icon('link') ?>Copier le lien</button></div><h1><?= e($ticket['title']) ?></h1><?php if($ticket['archived']): ?><div class="notice">Ce ticket est archivé.<form method="post" action="/tickets/<?= (int)$ticket['id'] ?>/archive"><?= csrf() ?><input type="hidden" name="restore" value="1"><button class="button subtle">Restaurer le ticket</button></form></div><?php endif; ?></section>
<div class="ticket-layout"><div class="ticket-main"><section class="panel ticket-edit-panel"><form method="post" action="/tickets/<?= (int)$ticket['id'] ?>" class="stack"><?= csrf() ?><input type="hidden" name="version" value="<?= (int)$ticket['version'] ?>"><input type="hidden" name="_return" value="/tickets/<?= (int)$ticket['id'] ?>"><label>Résumé<input name="title" value="<?= e($ticket['title']) ?>" required maxlength="240"></label><label>Avancement (%)<input type="number" name="progress_percent" min="0" max="100" step="1" value="<?= (int)$ticket['progress_percent'] ?>" required><small>De 0 à 100 %, indépendamment de l’état du ticket.</small></label><progress class="ticket-progress" max="100" value="<?= (int)$ticket['progress_percent'] ?>" aria-label="Avancement du ticket"></progress><label>Temps total estimé (heures)<input name="estimated_hours" inputmode="decimal" value="<?= e($ticket['estimated_hours']) ?>" placeholder="Ex. : 2,5" maxlength="9"><small>Durée de travail prévue pour cette tâche. Facultatif, deux décimales maximum.</small></label><label>Description<textarea name="description" rows="9" placeholder="L’essentiel et les détails utiles…"><?= e($ticket['description']) ?></textarea></label><div class="inline-fields"><label>État<select name="status"><?php foreach(Ticket::STATUSES as $v=>$l): ?><option value="<?= e($v) ?>" <?= $ticket['status']===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></label><label>Type<select name="type"><?php foreach(Ticket::TYPES as $v=>$l): ?><option value="<?= e($v) ?>" <?= $ticket['type']===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></label></div><div class="inline-fields"><label>Personne assignée<select name="assignee_id"><option value="">Non assigné</option><?php foreach($members as $m): ?><option value="<?= (int)$m['id'] ?>" <?= $ticket['assignee_id']===$m['id']?'selected':'' ?>><?= e($m['name']) ?></option><?php endforeach; ?></select></label><label>Priorité<select name="priority"><?php foreach(Ticket::PRIORITIES as $v=>$l): ?><option value="<?= e($v) ?>" <?= $ticket['priority']===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></label></div><div class="inline-fields"><label>Date de début<input type="date" name="start_date" value="<?= e($ticket['start_date']) ?>"></label><label>Échéance<input type="date" name="due_date" value="<?= e($ticket['due_date']) ?>"></label></div><label id="relations">Parent<select name="parent_id"><option value="">Aucun</option><?php foreach($parents as $p): ?><option value="<?= (int)$p['id'] ?>" <?= $ticket['parent_id']===$p['id']?'selected':'' ?>><?= e($project['project_key'].'-'.$p['number'].' · '.$p['title']) ?></option><?php endforeach; ?></select></label><label>Étiquettes<input name="labels" value="<?= e(implode(', ',$ticket['labels_array'])) ?>" placeholder="Séparées par une virgule"></label><label class="check-label"><input type="checkbox" name="flagged" value="1" <?= $ticket['flagged']?'checked':'' ?>>Ce ticket est bloqué</label><?php if($user['role']!=='viewer'): ?><button class="button primary">Enregistrer les modifications <?= icon('check') ?></button><?php endif; ?></form></section>
<section class="panel" id="activity"><h2>La conversation</h2><?php foreach($comments as $c): ?><article class="comment"><?= avatar($c['name'],'small',(int)$c['user_id']) ?><div><strong><?= e($c['name']) ?></strong><small><?= e($c['created_at']) ?></small><div class="conversation-content"><?= \App\Services\Conversation::render($c) ?></div></div></article><?php endforeach; if(!$comments): ?><p class="muted">Le contexte est souvent le meilleur point de départ.</p><?php endif; if($user['role']!=='viewer'): ?><form method="post" action="/tickets/<?= (int)$ticket['id'] ?>/comments" class="stack"><?= csrf() ?><input type="hidden" name="_return" value="/tickets/<?= (int)$ticket['id'] ?>"><div class="rich-composer" data-composer data-upload-url="/tickets/<?= (int)$ticket['id'] ?>/attachments">
<div class="editor-toolbar" role="toolbar" aria-label="Mise en forme du commentaire">
<button type="button" data-command="bold" aria-label="Gras" title="Gras (Ctrl+B)"><strong>G</strong></button><button type="button" data-command="italic" aria-label="Italique"><em>I</em></button><button type="button" data-command="underline" aria-label="Souligné"><u>S</u></button><button type="button" data-command="insertUnorderedList" aria-label="Liste à puces">• Liste</button><button type="button" data-command="insertOrderedList" aria-label="Liste numérotée">1. Liste</button><button type="button" data-command="createLink" aria-label="Insérer un lien">Lien</button><button type="button" data-command="removeFormat" aria-label="Effacer la mise en forme">Tx</button></div>
<div class="conversation-editor" contenteditable="true" role="textbox" aria-multiline="true" aria-label="Votre commentaire" data-placeholder="Une précision, une question, une avancée…"></div>
<textarea name="body" rows="3" maxlength="10000" placeholder="Votre commentaire" required data-comment-source></textarea>
<input type="hidden" name="body_format" value="text"><small>Collez une image avec Ctrl+V : elle sera ajoutée aux pièces jointes. 10 000 caractères maximum.</small><p class="upload-status" role="status" aria-live="polite"></p></div><button class="button subtle">Ajouter un commentaire</button></form><?php endif; ?></section></div>
<aside class="ticket-aside"><section class="panel"><h3>Dans les détails</h3><dl class="ticket-meta"><dt>Projet</dt><dd><?= e($project['name']) ?></dd><dt>Rapporteur</dt><dd><?= e($ticket['reporter_name']??'Externe') ?></dd><dt>Créé le</dt><dd><?= e(substr($ticket['created_at'],0,16)) ?></dd><dt>Mis à jour le</dt><dd><?= e(substr($ticket['updated_at'],0,16)) ?></dd><?php if($ticket['external_email']): ?><dt>Contact externe</dt><dd><?= e($ticket['external_email']) ?></dd><?php endif; ?></dl></section>
<section class="panel" id="attachments"><h3>Pièces jointes</h3><div data-attachment-list><?php foreach($attachments as $a): ?><div class="attachment-row" data-attachment-id="<?= (int)$a['id'] ?>"><a class="attachment" href="/attachments/<?= (int)$a['id'] ?>"><?= icon('download') ?><span><?= e($a['original_name']) ?><small><?= number_format($a['size_bytes']/1024,0,',',' ') ?> Ko</small></span></a><?php if($user['role']!=='viewer'): ?><form method="post" action="/attachments/<?= (int)$a['id'] ?>/delete"><?= csrf() ?><button class="tiny-button danger" aria-label="Supprimer <?= e($a['original_name']) ?>" data-confirm="Supprimer définitivement cette pièce jointe ? Elle disparaîtra aussi des images de la conversation.">×</button></form><?php endif; ?></div><?php endforeach; ?></div><?php if($user['role']!=='viewer'): ?><form method="post" enctype="multipart/form-data" action="/tickets/<?= (int)$ticket['id'] ?>/attachments" class="stack" data-file-queue><?= csrf() ?><input type="hidden" name="_return" value="/tickets/<?= (int)$ticket['id'] ?>"><label class="file-dropzone" data-dropzone>Déposez vos fichiers ici<span>ou choisissez des fichiers</span><input type="file" name="files[]" multiple required></label><small><?= (int)env('UPLOAD_MAX_MB','10') ?> Mo maximum par fichier · 20 fichiers maximum par envoi</small><ul class="pending-files" data-pending-files></ul><button class="button subtle small-button" data-upload-submit hidden>Joindre les fichiers</button><p role="status" aria-live="polite" data-upload-status></p></form><?php endif; ?></section>
<section class="panel"><h3>Tickets liés</h3><?php foreach($links as $link): ?><div class="linked-ticket"><a href="/tickets/<?= (int)$link['target_id'] ?>"><small><?= e(['relates'=>'Associé à','blocks'=>'Bloque','duplicates'=>'Doublon de'][$link['relation']]) ?></small><?= e($link['project_key'].'-'.$link['number'].' · '.$link['title']) ?></a><?php if($user['role']!=='viewer'): ?><form method="post" action="/links/<?= (int)$link['id'] ?>/delete"><?= csrf() ?><button class="tiny-button" aria-label="Retirer la relation">×</button></form><?php endif; ?></div><?php endforeach; if($user['role']!=='viewer'): ?><form method="post" action="/tickets/<?= (int)$ticket['id'] ?>/links" class="stack"><?= csrf() ?><input type="hidden" name="_return" value="/tickets/<?= (int)$ticket['id'] ?>"><select name="relation"><option value="relates">Associé à</option><option value="blocks">Bloque</option><option value="duplicates">Doublon de</option></select><select name="target_id" required><option value="">Choisir un ticket</option><?php foreach($parents as $p): ?><option value="<?= (int)$p['id'] ?>"><?= e($project['project_key'].'-'.$p['number'].' · '.$p['title']) ?></option><?php endforeach; ?></select><button class="button subtle small-button">Associer</button></form><?php endif; ?></section>
<?php if($children): ?><section class="panel"><h3>Tickets enfants</h3><?php foreach($children as $child): ?><a class="child-ticket" href="/tickets/<?= (int)$child['id'] ?>"><span class="legend-dot status-<?= e($child['status']) ?>"></span><?= e($child['title']) ?></a><?php endforeach; ?></section><?php endif; ?>
<?php if($events): ?><section class="panel"><h3>Développement</h3><?php foreach($events as $event): ?><a class="child-ticket" href="<?= e($event['external_url']) ?>" target="_blank" rel="noopener"><?= icon('code') ?><?= e($event['title']) ?></a><?php endforeach; ?></section><?php endif; ?>
<?php if(!$ticket['archived']&&$user['role']!=='viewer'): ?><form method="post" action="/tickets/<?= (int)$ticket['id'] ?>/archive"><?= csrf() ?><button class="button danger-outline" data-confirm="Archiver ce ticket ? Il sera retiré des listes et du tableau. Vous pourrez le restaurer depuis sa fiche.">Archiver ce ticket</button></form><?php endif; ?></aside></div>
